// Writes src/abi.ts from the Foundry artifacts in out/ (run `forge build` first). `pnpm gen:abi`.
import { readFileSync, writeFileSync } from "node:fs";

const artifact = (name: string) => new URL(`../../../out/${name}.sol/${name}.json`, import.meta.url);

/** The text src/abi.ts must have to match the compiled contracts. */
export function renderAbiModule(): string {
  const abi = (name: string): unknown => (JSON.parse(readFileSync(artifact(name), "utf8")) as { abi: unknown }).abi;
  return [
    "// Generated by `pnpm gen:abi` from the Foundry artifacts in out/. Do not edit.",
    "",
    `export const proofkinAbi = ${JSON.stringify(abi("Proofkin"), null, 2)} as const;`,
    "",
    `export const rendererAbi = ${JSON.stringify(abi("Renderer"), null, 2)} as const;`,
    "",
  ].join("\n");
}

if (import.meta.main) {
  writeFileSync(new URL("../src/abi.ts", import.meta.url), renderAbiModule());
  console.log("wrote src/abi.ts");
}
